--
-- Table structure for table `commandes`
--

DROP TABLE IF EXISTS `commandes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `commandes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `remise` double DEFAULT NULL,
  `prix_ht` double DEFAULT NULL,
  `prix_ttc` double DEFAULT NULL,
  `tva` double DEFAULT NULL,
  `timbre` double DEFAULT NULL,
  `etat` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `nom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prenom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adresse1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adresse2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pays` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Tunis',
  `region` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ville` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_postale` int DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `livraison` int DEFAULT NULL,
  `frais_livraison` double DEFAULT NULL,
  `livraison_nom` text COLLATE utf8mb4_unicode_ci,
  `livraison_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_prenom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_adresse1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_adresse2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_region` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_ville` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `livraison_code_postale` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `historique` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=966 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

