INSERT INTO `coordinates` VALUES (1,NULL,'STE SOBITAS','1411068/Q/A/M/000','12503000003301717490','contact@protein.tn','Rue Ribat, 4000 Sousse Tunisie','+216 27 612 500','+216 73 200 169',NULL,'www.protein.tn','https://www.facebook.com/sobitass/','https://www.youtube.com/@sobitas6850',NULL,'coordonnees/September2023/OXC3oL0LreP3RCsgR3k6.webp','coordonnees/June2023/KLFomKZY9tcaP4rJ6Tdb.png',NULL,'PROTEINE TUNISIE - SOBITAS\r\nDepuis 2010, nous sommes votre partenaire de confiance en compléments alimentaires sportifs et matériel de musculation en Tunisie. Que vous cherchiez à booster vos performances, à prendre de la masse ou à perdre du poids, nous vous proposons des produits certifiés comme la whey protéine, la créatine, les BCAA, les oméga-3, et bien plus encore.\r\nDécouvrez également notre large choix de matériel de musculation professionnel : bancs, haltères, barres, gants, machines cardio et accessoires fitness.\r\nLivraison rapide dans toutes les villes de Tunisie : Sousse, Tunis, Sfax, Gabès et au-delà.\r\nContactez-nous :\r\nEmail : contact@protein.tn\r\nAdresse : Rue Ribat, 4000 Sousse, Tunisie',NULL,NULL,NULL,'2023-05-20 11:23:37','2025-12-22 13:32:37',1,19,'Bienvenue chez SOBITAS','SOBITAS vous remercie de votre visite','B91142842015','Arrête la présente facture à la somme de :','https://twitter.com/TunisieProteine','https://www.instagram.com/sobitass/','https://www.linkedin.com/',NULL,10,'Nous facilitons la consolidation, le marketing et le suivi de votre site Web de médias sociaux.','Rejoignez plus de 60000 abonnés et obtenez un nouveau coupon de réduction chaque mercredi.','SOBITAS App est maintenant disponible sur Google Play & App Store. Obtenez-le maintenant.','https://play.google.com/store/apps/details?id=io.abdelbari.sobitas','https://play.google.com/store/apps/details?id=io.abdelbari.sobitas','<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3234.5147066818377!2d10.628044074612736!3d35.83638072143763!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x130275a0040618e1%3A0xafd9534eef29955a!2sPROTEINE%20SOUSSE%20%3A%20SOBITAS!5e0!3m2!1sfr!2sus!4v1697971736612!5m2!1sfr!2sus\" width=\"100%\" height=\"300\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>','PROTEINE TUNISIE','https://wa.me/21627612500','https://www.tiktok.com/@sobitassousse?_t=8fxdJ9IKeur&_r=1','Questions fréquemment posées',NULL);
