  `promo_ht` double DEFAULT NULL,
  `promo` double DEFAULT NULL,
  `description_fr` text COLLATE utf8mb4_unicode_ci,
  `publier` int DEFAULT NULL,
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `code_product` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pack` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_id` int DEFAULT NULL,
  `new_product` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `best_seller` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gallery` text COLLATE utf8mb4_unicode_ci,
  `note` int DEFAULT NULL,
  `meta_description_fr` text COLLATE utf8mb4_unicode_ci,
  `promo_expiration_date` timestamp NULL DEFAULT NULL,
  `rupture` int DEFAULT '1',
  `alt_cover` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description_cover` text COLLATE utf8mb4_unicode_ci,
  `meta` text COLLATE utf8mb4_unicode_ci,
  `content_seo` text COLLATE utf8mb4_unicode_ci,
  `review` text COLLATE utf8mb4_unicode_ci,
  `aggregateRating` text COLLATE utf8mb4_unicode_ci,
  `nutrition_values` text COLLATE utf8mb4_unicode_ci,
  `questions` text COLLATE utf8mb4_unicode_ci,
  `zone1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Description',
  `zone2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Avis client',
  `zone3` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Valeurs nutritionnelles',
  `zone4` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Questions',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=508 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
